(function() {
  "use strict";

  var PAGE_SIZE = 20;
  var REFRESH_INTERVAL_MS = 600000;
  var STATIC_CACHE_TTL_MS = 1800000;
  var standings = [];
  var filtered = [];
  var detailsById = {};
  var affiliationById = {};
  var categories = [];
  var challengeCategoryById = {};
  var selectedTab = "all";
  var currentPage = 1;
  var updateInFlight = false;
  var cachedAffiliationRows = null;
  var cachedChallengeRows = null;
  var staticCacheAt = 0;
  var resizeGraphTimer = null;
  var graphChart = null;

  function htmlEntities(value) {
    return $("<div/>").text(value == null ? "" : String(value)).html();
  }

  function safeFromNow(value) {
    if (!value) return "-";
    var date = new Date(value);
    if (isNaN(date.getTime())) return "-";
    var diffMs = Math.max(0, Date.now() - date.getTime());
    var minute = 60 * 1000;
    var hour = 60 * minute;
    var day = 24 * hour;
    var year = 365 * day;
    if (diffMs < minute) return "just now";
    if (diffMs < hour) {
      var minutes = Math.floor(diffMs / minute);
      return minutes === 1 ? "a minute ago" : minutes + " minutes ago";
    }
    if (diffMs < day) {
      var hours = Math.floor(diffMs / hour);
      return hours === 1 ? "an hour ago" : hours + " hours ago";
    }
    if (diffMs < year) {
      var days = Math.floor(diffMs / day);
      return days === 1 ? "a day ago" : days + " days ago";
    }
    var years = Math.floor(diffMs / year);
    return years === 1 ? "a year ago" : years + " years ago";
  }

  function getDisplayName() {
    return window.CTFd && CTFd.config && CTFd.config.userMode === "teams" ? "Team" : "User";
  }

  function getCurrentAccountId() {
    if (window.init && window.init.userMode === "teams") {
      return window.init.teamId || null;
    }
    return window.init && typeof window.init.userId !== "undefined" ? window.init.userId : null;
  }

  function getInitialCategory() {
    try {
      var params = new URLSearchParams(window.location.search);
      return params.get("category") || "all";
    } catch (e) {
      return "all";
    }
  }

  function fetchAllAffiliations(page, carry) {
    page = page || 1;
    carry = carry || [];
    if (!window.CTFd || !CTFd.api) return Promise.resolve(carry);
    var request = CTFd.config.userMode === "teams" ? CTFd.api.get_team_list({ page: page }) : CTFd.api.get_user_list({ page: page });
    return request.then(function(response) {
      var rows = (response && response.data) || [];
      var meta = response && response.meta && response.meta.pagination;
      var merged = carry.concat(rows);
      return meta && meta.next ? fetchAllAffiliations(meta.next, merged) : merged;
    });
  }

  function fetchStandings() {
    if (!window.CTFd || !CTFd.api) return Promise.resolve([]);
    return CTFd.api.get_scoreboard_list().then(function(response) {
      return (response && response.data) || [];
    });
  }

  function fetchDetails(count) {
    if (!window.CTFd || !CTFd.api || !count) return Promise.resolve({});
    return CTFd.api.get_scoreboard_detail({ count: count }).then(function(response) {
      return (response && response.data) || {};
    });
  }

  function fetchChallenges() {
    if (!window.CTFd || !CTFd.api) return Promise.resolve([]);
    return CTFd.api.get_challenge_list().then(function(response) {
      return (response && response.data) || [];
    }).catch(function() {
      return [];
    });
  }

  function getStaticRows(forceRefresh) {
    var now = Date.now();
    var cacheValid =
      !forceRefresh &&
      cachedAffiliationRows !== null &&
      cachedChallengeRows !== null &&
      now - staticCacheAt < STATIC_CACHE_TTL_MS;

    if (cacheValid) {
      return Promise.resolve({
        affiliations: cachedAffiliationRows,
        challenges: cachedChallengeRows
      });
    }

    return Promise.all([fetchAllAffiliations(), fetchChallenges()]).then(function(results) {
      cachedAffiliationRows = results[0] || [];
      cachedChallengeRows = results[1] || [];
      staticCacheAt = Date.now();
      return {
        affiliations: cachedAffiliationRows,
        challenges: cachedChallengeRows
      };
    });
  }

  function buildMaps(detailResponse, affiliationRows, challengeRows) {
    detailsById = {};
    affiliationById = {};
    categories = [];
    challengeCategoryById = {};

    for (var c = 0; c < challengeRows.length; c++) {
      var challenge = challengeRows[c];
      if (!challenge || typeof challenge.id === "undefined") continue;
      var category = challenge.category || "Other";
      challengeCategoryById[String(challenge.id)] = category;
      if (categories.indexOf(category) === -1) categories.push(category);
    }
    categories.sort();

    var keys = Object.keys(detailResponse || {});
    for (var i = 0; i < keys.length; i++) {
      var accountId = keys[i];
      var entry = detailResponse[accountId];
      if (!entry) continue;

      var solves = entry.solves || [];
      var byCategory = {};
      for (var s = 0; s < solves.length; s++) {
        var solve = solves[s];
        if (!solve || !solve.challenge_id) continue;
        var cat = challengeCategoryById[String(solve.challenge_id)] || "Other";
        var cur = byCategory[cat] || { score: 0, solves: 0, lastPoint: null };
        cur.score += Number(solve.value) || 0;
        cur.solves += 1;
        cur.lastPoint = solve.date;
        byCategory[cat] = cur;
      }

      detailsById[String(accountId)] = {
        solves: solves.length,
        lastPoint: solves.length ? solves[solves.length - 1].date : null,
        rawSolves: solves,
        byCategory: byCategory
      };
    }

    for (var j = 0; j < affiliationRows.length; j++) {
      var row = affiliationRows[j];
      if (!row || typeof row.id === "undefined") continue;
      affiliationById[String(row.id)] = row.affiliation || "-";
    }
  }

  function applyFilter() {
    if (selectedTab === "all") {
      filtered = standings.slice();
    } else {
      filtered = standings
        .map(function(item) {
          var detail = detailsById[String(item.account_id)] || {};
          var cat = (detail.byCategory && detail.byCategory[selectedTab]) || { score: 0, solves: 0, lastPoint: null };
          return $.extend({}, item, { _category: cat });
        })
        .filter(function(item) {
          return item._category.score > 0 || item._category.solves > 0;
        })
        .sort(function(a, b) {
          if (b._category.score !== a._category.score) return b._category.score - a._category.score;
          return b._category.solves - a._category.solves;
        });
    }

    var maxPage = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
    if (currentPage > maxPage) currentPage = maxPage;
  }

  function renderTabs() {
    var box = $("#scoreboard-tabs");
    box.empty();

    function addTab(name, value) {
      var href = value === "all" ? "/scoreboard" : "/scoreboard?category=" + encodeURIComponent(value);
      box.append(
        "<li class='nav-item'>" +
          "<a class='nav-link scoreboard-tab " + (selectedTab === value ? "active" : "") + "' href='" + href + "' data-value='" + htmlEntities(value) + "'>" + htmlEntities(name) + "</a>" +
        "</li>"
      );
    }

    addTab("All", "all");
    for (var i = 0; i < categories.length; i++) addTab(categories[i], categories[i]);
  }

  function renderRows() {
    var body = $("#scoreboard-body");
    var empty = $("#scoreboard-empty");
    body.empty();
    if (!filtered.length) {
      empty.removeClass("d-none");
      return;
    }
    empty.addClass("d-none");

    var start = (currentPage - 1) * PAGE_SIZE;
    var end = Math.min(start + PAGE_SIZE, filtered.length);
    for (var i = start; i < end; i++) {
      var row = filtered[i];
      var detail = detailsById[String(row.account_id)] || { solves: 0, lastPoint: null };
      var affiliation = affiliationById[String(row.account_id)] || "-";
      var place = selectedTab === "all" ? row.pos : i + 1;
      var score = selectedTab === "all" ? row.score : row._category.score;
      var solves = selectedTab === "all" ? detail.solves : row._category.solves;
      var lastPoint = selectedTab === "all" ? detail.lastPoint : row._category.lastPoint;

      body.append(
        "<tr>" +
          "<td>" + htmlEntities(place) + "</td>" +
          "<td><a href='" + htmlEntities(row.account_url || "#") + "'>" + htmlEntities(row.name) + "</a></td>" +
          "<td>" + htmlEntities(affiliation) + "</td>" +
          "<td>" + htmlEntities(score) + "</td>" +
          "<td>" + htmlEntities(solves) + "</td>" +
          "<td>" + htmlEntities(safeFromNow(lastPoint)) + "</td>" +
        "</tr>"
      );
    }
  }

  function renderPagination() {
    var pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
    var box = $("#scoreboard-pagination");
    box.empty();

    function addNav(label, page, disabled, extraClass) {
      box.append(
        "<li class='page-item " + (disabled ? "disabled" : "") + "'>" +
          "<a class='page-link scoreboard-page " + (extraClass || "") + " " + (disabled ? "scoreboard-page-disabled" : "") + "' href='#' data-page='" + page + "'>" + label + "</a>" +
        "</li>"
      );
    }

    function addPage(page) {
      box.append(
        "<li class='page-item " + (page === currentPage ? "active" : "") + "'><a class='page-link scoreboard-page' href='#' data-page='" + page + "'>" + page + "</a></li>"
      );
    }

    function addEllipsis() {
      box.append("<li class='page-item disabled'><span class='page-link'>...</span></li>");
    }

    addNav("First", 1, currentPage === 1, "first");
    addNav("Prev", currentPage - 1, currentPage === 1, "prev");

    var pages = [1];
    for (var p = currentPage - 1; p <= currentPage + 1; p++) if (p > 1 && p < pageCount) pages.push(p);
    if (pageCount > 1) pages.push(pageCount);
    pages = pages.filter(function(value, index, arr) { return arr.indexOf(value) === index; }).sort(function(a, b) { return a - b; });
    for (var i = 0; i < pages.length; i++) {
      if (i > 0 && pages[i] - pages[i - 1] > 1) addEllipsis();
      addPage(pages[i]);
    }

    addNav("Next", currentPage + 1, currentPage === pageCount, "next");
    addNav("Last", pageCount, currentPage === pageCount, "last");
  }

  function hashColor(value) {
    var hash = 0;
    var input = String(value || "");
    for (var i = 0; i < input.length; i++) {
      hash = input.charCodeAt(i) + ((hash << 5) - hash);
      hash |= 0;
    }

    return "hsl(" + ((hash % 360) + 360) % 360 + ", 75%, 55%)";
  }

  function escapeXml(value) {
    return String(value == null ? "" : value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/\"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function buildGraphSeries(rows) {
    var series = [];
    var minTime = null;
    var maxTime = null;
    var maxValue = 0;

    for (var i = 0; i < rows.length; i++) {
      var row = rows[i];
      var detail = detailsById[String(row.account_id)] || { rawSolves: [] };
      var rawSolves = detail.rawSolves || [];
      var points = [];
      var total = 0;

      for (var j = 0; j < rawSolves.length; j++) {
        var solve = rawSolves[j];
        if (!solve || !solve.date) {
          continue;
        }

        var timestamp = new Date(solve.date).getTime();
        if (isNaN(timestamp)) {
          continue;
        }

        total += Number(solve.value) || 0;
        points.push([timestamp, total]);

        if (minTime === null || timestamp < minTime) {
          minTime = timestamp;
        }
        if (maxTime === null || timestamp > maxTime) {
          maxTime = timestamp;
        }
        if (total > maxValue) {
          maxValue = total;
        }
      }

      if (points.length) {
        series.push({
          name: row.name,
          id: row.account_id,
          color: hashColor(row.name + row.account_id),
          points: points
        });
      }
    }

    return {
      series: series,
      minTime: minTime,
      maxTime: maxTime,
      maxValue: maxValue
    };
  }

  function renderGraph() {
    return;
  }

  function updatePlaceText() {
    var currentAccountId = getCurrentAccountId();
    if (currentAccountId === null || typeof currentAccountId === "undefined") {
      $("#scoreboard-place-text").text("");
      return;
    }

    var myPlace = null;
    if (selectedTab === "all") {
      for (var i = 0; i < standings.length; i++) {
        if (String(standings[i].account_id) === String(currentAccountId)) {
          myPlace = standings[i].pos;
          break;
        }
      }
    } else {
      for (var j = 0; j < filtered.length; j++) {
        if (String(filtered[j].account_id) === String(currentAccountId)) {
          myPlace = j + 1;
          break;
        }
      }
    }

    var label = selectedTab === "all" ? "Your place" : "Your place in " + selectedTab;
    $("#scoreboard-place-text").text(myPlace ? label + ": " + myPlace : "");
  }

  function renderAll() {
    applyFilter();
    renderTabs();
    renderRows();
    renderPagination();
    renderGraph();
    updatePlaceText();
  }

  function update(forceRefreshStatic) {
    if (updateInFlight) {
      return Promise.resolve();
    }

    updateInFlight = true;
    return Promise.all([fetchStandings(), getStaticRows(!!forceRefreshStatic)])
      .then(function(results) {
        standings = results[0] || [];
        var staticRows = results[1] || {};
        return fetchDetails(standings.length).then(function(detailResponse) {
          buildMaps(detailResponse, staticRows.affiliations || [], staticRows.challenges || []);
          if (selectedTab !== "all" && categories.indexOf(selectedTab) === -1) selectedTab = "all";
          renderAll();
        });
      })
      .finally(function() {
        updateInFlight = false;
      });
  }

  $(function() {
    selectedTab = getInitialCategory();
    update(true);

    setInterval(function() {
      if (document.hidden) {
        return;
      }
      update(false);
    }, REFRESH_INTERVAL_MS);

    document.addEventListener("visibilitychange", function() {
      if (!document.hidden) {
        update(false);
      }
    });

    $(window).on("resize", function() {
      clearTimeout(resizeGraphTimer);
      resizeGraphTimer = setTimeout(function() {
        return;
      }, 100);
    });

    $(document).on("click", ".scoreboard-tab", function(event) {
      event.preventDefault();
      selectedTab = $(this).data("value") || "all";
      currentPage = 1;
      try {
        var newUrl = selectedTab === "all" ? "/scoreboard" : "/scoreboard?category=" + encodeURIComponent(selectedTab);
        window.history.replaceState({}, "", newUrl);
      } catch (e) {}
      renderAll();
    });

    $(document).on("click", ".scoreboard-page", function(event) {
      event.preventDefault();
      if ($(this).hasClass("scoreboard-page-disabled") || $(this).parent().hasClass("disabled")) return;
      var target = parseInt($(this).data("page"), 10) || 1;
      var pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
      if (target < 1) target = 1;
      if (target > pageCount) target = pageCount;
      currentPage = target;
      renderRows();
      renderPagination();
    });
  });
})();
